}

.care--today {
  background: var(--card);
}

.care--coming {
  background: transparent;
  border-style: dashed;
  border-color: var(--ink-soft);
  box-shadow: none;
}

.care--done {
  background: var(--moss-soft);
  border-color: var(--moss-deep);
