}

.chip--today {
  background: var(--ochre);
}

.chip--coming {
  background: var(--moss-soft);
  color: var(--moss-deep);
}

.chip--done {
  background: var(--moss-deep);
  color: var(--card);
}

.care__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
