}

.btn {
  min-height: 44px;
  padding: 8px 18px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--card);
  color: var(--ink);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn--primary {
  flex: 1 1 150px;
  background: var(--moss-deep);
  border-color: var(--moss-deep);
  color: var(--card);
}

.btn--quiet {
  background: transparent;
  border-style: dashed;
}

.btn--undo {
  flex: none;
  min-height: 40px;
  background: var(--ochre);
  border-color: var(--ochre);
  color: var(--ink);
}

