  background: var(--drop);
  pointer-events: none;
  animation: drop 0.7s ease-in forwards;
}

.is-perking {
  animation: perk 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.zzz {
  position: absolute;
  top: -6px;
  right: 22px;
  font-weight: 800;
  color: var(--plum);
  pointer-events: none;
  animation: zzz 1.6s ease-out forwards;
}

@keyframes drop {
  0% {
    opacity: 0;
    transform: translateY(-14px);
  }
  15% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(44px);
  }
}

@keyframes perk {
  0% {
    transform: scale(1);
