/* Rail: windowsill and the seven-day rhythm. */

.sill {
  display: flex;
  align-items: flex-end;
  justify-content: space-evenly;
  gap: 8px;
  padding: 8px 18px 0;
  background: var(--sand);
  border: 2px solid var(--ink);
  border-bottom: 14px solid var(--wood);
  border-radius: 28px 36px 12px 12px;
}

.sill__plant {
  display: flex;
  justify-content: center;
  transform-origin: 50% 100%;
  transition: transform 0.7s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.sill__plant svg {
  width: 72px;
  height: 72px;
}

.sill__plant.is-overdue {
  transform: rotate(-14deg) translateX(-6px);
}

.sill__plant.is-done {
  transform: scale(1.06);
}

.rhythm {
  margin-top: 28px;
}

.rhythm__note {
  margin: 0 0 14px;
  font-size: 0.9375rem;
  color: var(--ink-soft);
}

.rhythm__list {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  height: 136px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rhythm__day {
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  height: 100%;
}

.rhythm__count {
  font-size: 0.8125rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.rhythm__bar {
  align-self: end;
  width: min(100%, 30px);
  height: max(6px, calc(var(--n) * 16px));
  border-radius: 999px 999px 8px 8px;
  background: var(--moss);
  transition: height 0.6s cubic-bezier(0.3, 1.4, 0.5, 1);
}

.rhythm__day.is-today .rhythm__bar {
  background: var(--clay);
}

.rhythm__label {
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--ink-soft);
}

.rhythm__day.is-today .rhythm__label {
  color: var(--ink);
  font-weight: 800;
}

/* Undo toast */

.toast {
  position: fixed;
  left: 50%;
  bottom: 20px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(460px, calc(100% - 32px));
  padding: 10px 10px 10px 20px;
  background: var(--ink);
  color: var(--card);
  border-radius: 999px;
  box-shadow: 0 12px 28px rgba(43, 35, 25, 0.28);
  transform: translateX(-50%);
  animation: toast-in 0.35s cubic-bezier(0.3, 1.4, 0.5, 1);
}

.toast__text {
  flex: 1;
  margin: 0;
  font-weight: 700;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translate(-50%, 16px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

/* Wide screens: give the queue room and let details spread out. */

@media (min-width: 900px) {
  .brand__name {
    font-size: 2.3rem;
  }

  .lede {
    font-size: 1.45rem;
  }

  .queue__title {
    font-size: 1.85rem;
  }

  .care {
    padding: 20px 22px 18px;
  }

  .care__row {
    grid-template-columns: 96px minmax(0, 1fr);
  }

  .care__avatar {
    width: 96px;
    height: 96px;
  }

  .care__name {
    font-size: 1.3rem;
  }
}

/* Reduced motion: keep every state change, drop the movement. */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }

  .drop,
  .zzz {
    display: none !important;
  }
}

