}

.care--overdue {
  background: #fdeee4;
  border-width: 3px;
  transform: rotate(-0.35deg);
}

.care--today {
  background: var(--card);
}

.care--coming {
  background: transparent;
  border-style: dashed;
  border-color: var(--ink-soft);
  box-shadow: none;
}

.care--done {
  background: var(--moss-soft);
  border-color: var(--moss-deep);
  box-shadow: none;
}

.sticker {
  position: absolute;
  top: -13px;
  right: 14px;
  padding: 2px 12px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--ochre);
  color: var(--ink);
  font-size: 0.8125rem;
  font-weight: 800;
  transform: rotate(4deg);
}

.care__row {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
}

.care__avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 76px;
  height: 76px;
  background: var(--moss-soft);
  border: 2px solid var(--ink);
  border-radius: var(--shape-blob);
}

.care__avatar svg {
  width: 74%;
  height: 74%;
}

.care--fern .care__avatar {
  background: var(--moss-soft);
}

.care--pothos .care__avatar {
  background: var(--ochre-soft);
}

.care--cactus .care__avatar {
  background: var(--clay-soft);
}

.care--calathea .care__avatar {
  background: var(--plum-soft);
}

.care__name {
  margin: 0;
  font-size: 1.125rem;
  line-height: 1.2;
}

.care__species {
  font-size: 0.9375rem;
  color: var(--ink-soft);
}

.care__task {
  margin: 2px 0 0;
  font-size: 0.9375rem;
  font-weight: 700;
}

.care__mood {
  margin: 6px 0 0;
  font-size: 0.9375rem;
  font-style: italic;
  color: var(--ink-soft);
}

.care__due {
  margin: 8px 0 0;
}

.chip {
  display: inline-block;
  padding: 2px 12px;
  border-radius: 999px;
  background: var(--sand);
  color: var(--ink);
  font-size: 0.875rem;
  font-weight: 800;
}

.chip--overdue {
  background: var(--clay-deep);
  color: #fff8f0;
}

.chip--today {
  background: var(--ochre);
}

.chip--coming {
  background: var(--moss-soft);
  color: var(--moss-deep);
}

.chip--done {
  background: var(--moss-deep);
  color: var(--card);
}

.care__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.btn {
  min-height: 44px;
  padding: 8px 18px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--card);
  color: var(--ink);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn--primary {
  flex: 1 1 150px;
  background: var(--moss-deep);
  border-color: var(--moss-deep);
  color: var(--card);
}

.btn--quiet {
  background: transparent;
  border-style: dashed;
}

.btn--undo {
  flex: none;
  min-height: 40px;
  background: var(--ochre);
  border-color: var(--ochre);
  color: var(--ink);
}

.toast :focus-visible {
  outline-color: var(--ochre);
}

/* Details: light, water, and observation history, opened in place. */

.care__details {
  display: grid;
  gap: 14px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 2px dashed var(--rule);
}

.facts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 20px;
  margin: 0;
}

.facts div {
  display: flex;
  gap: 6px;
}

.facts dt {
  font-size: 0.875rem;
  color: var(--ink-soft);
}

.facts dt::after {
  content: ":";
}

.facts dd {
  margin: 0;
  font-size: 0.9375rem;
  font-weight: 800;
}

.logs {
  display: grid;
