  text-transform: uppercase;
  color: var(--ink-soft);
}

.logs ul {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.logs li {
  font-size: 0.9375rem;
}

.when {
  display: inline-block;
  min-width: 4.8em;
  margin-right: 4px;
  font-weight: 800;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.logs .empty {
  font-style: italic;
  color: var(--ink-soft);
}

@media (min-width: 640px) {
  .logs {
