/* Small moments of delight: a droplet, a perk, a sleepy z. */

.drop {
  position: absolute;
  top: 0;
  left: 50%;
  width: 9px;
  height: 13px;
  margin-left: -4.5px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: var(--drop);
  pointer-events: none;
  animation: drop 0.7s ease-in forwards;
}

.is-perking {
  animation: perk 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.zzz {
  position: absolute;
  top: -6px;
  right: 22px;
  font-weight: 800;
  color: var(--plum);
  pointer-events: none;
  animation: zzz 1.6s ease-out forwards;
}

@keyframes drop {
  0% {
    opacity: 0;
    transform: translateY(-14px);
  }
  15% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(44px);
  }
}

@keyframes perk {
  0% {
    transform: scale(1);
  }
  40% {
    transform: scale(0.92) rotate(-4deg);
  }
  70% {
    transform: scale(1.08) rotate(3deg);
  }
  100% {
    transform: scale(1) rotate(0);
  }
}

@keyframes zzz {
  0% {
    opacity: 0;
    transform: translateY(8px);
  }
  20% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(-26px);
  }
}

/* Rail: windowsill and the seven-day rhythm. */

.sill {
  display: flex;
  align-items: flex-end;
  justify-content: space-evenly;
  gap: 8px;
  padding: 8px 18px 0;
  background: var(--sand);
  border: 2px solid var(--ink);
  border-bottom: 14px solid var(--wood);
  border-radius: 28px 36px 12px 12px;
}

.sill__plant {
  display: flex;
  justify-content: center;
  transform-origin: 50% 100%;
  transition: transform 0.7s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.sill__plant svg {
  width: 72px;
  height: 72px;
}

.sill__plant.is-overdue {
  transform: rotate(-14deg) translateX(-6px);
}

.sill__plant.is-done {
  transform: scale(1.06);
}

.rhythm {
  margin-top: 28px;
}

.rhythm__note {
  margin: 0 0 14px;
  font-size: 0.9375rem;
  color: var(--ink-soft);
}

.rhythm__list {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  height: 136px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rhythm__day {
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  height: 100%;
}

.rhythm__count {
  font-size: 0.8125rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.rhythm__bar {
  align-self: end;
  width: min(100%, 30px);
  height: max(6px, calc(var(--n) * 16px));
  border-radius: 999px 999px 8px 8px;
  background: var(--moss);
  transition: height 0.6s cubic-bezier(0.3, 1.4, 0.5, 1);
}

.rhythm__day.is-today .rhythm__bar {
  background: var(--clay);
}

.rhythm__label {
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--ink-soft);
}

.rhythm__day.is-today .rhythm__label {
  color: var(--ink);
  font-weight: 800;
}

/* Undo toast */

.toast {
  position: fixed;
  left: 50%;
  bottom: 20px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(460px, calc(100% - 32px));
  padding: 10px 10px 10px 20px;
  background: var(--ink);
  color: var(--card);
  border-radius: 999px;
  box-shadow: 0 12px 28px rgba(43, 35, 25, 0.28);
  transform: translateX(-50%);
  animation: toast-in 0.35s cubic-bezier(0.3, 1.4, 0.5, 1);
}

.toast__text {
  flex: 1;
  margin: 0;
  font-weight: 700;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translate(-50%, 16px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

