:root {
  --paper: #f6efe0;
  --card: #fffaf1;
  --sand: #ede2c8;
  --ink: #2b2319;
  --ink-soft: #5b4e3f;
  --rule: #cbbb9a;
  --moss: #5d7d3f;
  --moss-deep: #334d20;
  --moss-soft: #dfe7c9;
  --clay: #c4693e;
  --clay-deep: #7a3414;
  --clay-soft: #f6dccb;
  --ochre: #e3a72f;
  --ochre-soft: #f8e7b8;
  --plum: #6e4f80;
  --plum-soft: #e9dfee;
  --wood: #b98b5e;
  --drop: #5f9bbd;

  --shape-a: 34px 42px 30px 46px / 38px 30px 44px 32px;
  --shape-b: 46px 28px 40px 34px / 30px 44px 28px 40px;
  --shape-blob: 46% 54% 52% 48% / 52% 44% 56% 48%;

  --font: ui-rounded, "SF Pro Rounded", "Hiragino Maru Gothic ProN", "Nunito", system-ui,
    -apple-system, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.5;
  color: var(--ink);
  background-color: var(--paper);
  background-image: radial-gradient(rgba(43, 35, 25, 0.07) 1px, transparent 1.6px);
  background-size: 16px 16px;
  -webkit-text-size-adjust: 100%;
}

:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 3px;
}

#queue-title:focus {
  outline: none;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -80px;
  z-index: 10;
  padding: 10px 16px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--card);
  font-weight: 800;
  text-decoration: none;
}

