  top: 12px;
}

/* Layout: one column on phones; on wide screens a brand rail beside a roomy queue. */

.layout {
  display: grid;
  gap: 32px;
  max-width: 1180px;
  margin: 0 auto;
  padding: 24px 16px 150px;
  grid-template-areas: "hero" "queue" "rail";
}

.hero {
  grid-area: hero;
}

.queue {
  grid-area: queue;
  min-width: 0;
}

.rail {
  grid-area: rail;
}

@media (min-width: 900px) {
  .layout {
    grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
    grid-template-rows: auto 1fr;
    grid-template-areas: "hero queue" "rail queue";
    align-items: start;
    gap: 40px 64px;
    padding: 56px 40px 80px;
  }

  .rail {
    position: sticky;
    top: 40px;
    align-self: start;
  }
}

